CREATE FUNCTION payiq_private.protect_pending_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.simulation_transfers WHERE sync_request_id=OLD.id AND status='AWAITING_USER_AUTH') AND (NEW.direction IS DISTINCT FROM OLD.direction OR NEW.amount IS DISTINCT FROM OLD.amount OR NEW.amount_type IS DISTINCT FROM OLD.amount_type OR NEW.max_cap IS DISTINCT FROM OLD.max_cap OR NEW.counterparty_address IS DISTINCT FROM OLD.counterparty_address OR NEW.counterparty_email IS DISTINCT FROM OLD.counterparty_email OR NEW.policy_id IS DISTINCT FROM OLD.policy_id) THEN RAISE EXCEPTION 'Decline or cancel the pending request before changing its amount, recipient or policy'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION payiq_private.protect_pending_sync() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER protect_pending_sync BEFORE UPDATE ON public.sync_requests FOR EACH ROW EXECUTE FUNCTION payiq_private.protect_pending_sync();
CREATE FUNCTION payiq_private.protect_terminal_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NEW.sync_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.sync_requests WHERE id=NEW.sync_request_id AND status IN ('COMPLETED','CANCELLED')) THEN RAISE EXCEPTION 'This Smart Transfer is no longer active'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION payiq_private.protect_terminal_sync() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER protect_terminal_sync BEFORE INSERT ON public.simulation_transfers FOR EACH ROW EXECUTE FUNCTION payiq_private.protect_terminal_sync();
CREATE FUNCTION payiq_private.due_failure_reminder() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE old_claim text:=current_setting('request.jwt.claim.sub',true); BEGIN IF NEW.sync_request_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.sync_requests WHERE id=NEW.sync_request_id AND reminder_cadence='DUE_FAILURE') AND ((TG_OP='INSERT' AND NEW.status='AWAITING_USER_AUTH') OR (TG_OP='UPDATE' AND NEW.status='FAILED' AND NEW.status IS DISTINCT FROM OLD.status)) THEN PERFORM set_config('request.jwt.claim.sub',NEW.requester_id::text,true); PERFORM payiq_private.send_smart_reminder(NEW.sync_request_id); PERFORM set_config('request.jwt.claim.sub',coalesce(old_claim,''),true); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION payiq_private.due_failure_reminder() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_due_failure_reminder AFTER INSERT OR UPDATE ON public.simulation_transfers FOR EACH ROW EXECUTE FUNCTION payiq_private.due_failure_reminder();